"""Generates docs/API_DOCUMENTATION.md from the routers in backend/app/api (AST only, no imports): method, path, auth rule, docstring.  Run: python tools/gen_api_docs.py"""
import ast, pathlib
root = pathlib.Path(__file__).parents[1]; rows = []
AUTH = {"current_user": "login (Bearer token)", "admin_only": "admin login", "ingest_auth": "device key (X-Device-Key) or login", "export_auth": "login or read-only X-Export-Key", "elder_auth": "person access code (X-Elder-Code)"}
for f in sorted((root / "backend/app/api").glob("*.py")):
    t = ast.parse(f.read_text(encoding="utf-8"))
    for n in t.body:
        if not isinstance(n, ast.FunctionDef): continue
        for d in n.decorator_list:
            if isinstance(d, ast.Call) and isinstance(d.func, ast.Attribute) and d.func.attr in ("get", "post", "put", "delete") and getattr(d.func.value, "id", "") == "router":
                deps = {a.args[0].id for a in n.args.defaults if isinstance(a, ast.Call) and getattr(a.func, "id", "") == "Depends" and a.args and isinstance(a.args[0], ast.Name)}
                auth = next((AUTH[x] for x in ("admin_only", "export_auth", "ingest_auth", "elder_auth", "current_user") if x in deps), "public")
                body = next((ast.unparse(a.annotation) for a in n.args.args if a.annotation is not None and a.arg == "b"), "")
                rows.append((f.stem, d.func.attr.upper(), d.args[0].value, auth, body, (ast.get_docstring(n) or "").split("\n")[0]))
out = ["# API reference", "", "Generated by `tools/gen_api_docs.py` from the code (do not edit by hand). Interactive docs: `/docs` (Swagger UI) when the backend runs.",
       "Auth: `Authorization: Bearer <token>` from `POST /auth/login`; cameras/AI services/wearables use `X-Device-Key`; the elder's own screen uses `X-Elder-Code`.",
       "Send `Accept-Language: ar` or `en` to get messages in that language. Caregivers only see people assigned to them; admins see everyone.", "",
       "| Module | Method | Path | Auth | Body | What it does |", "|---|---|---|---|---|---|"]
out += [f"| {m} | {v} | `{p}` | {a} | {('`' + b + '`') if b else ''} | {doc} |" for m, v, p, a, b, doc in rows]
out += ["", "## Accelerometer endpoint (wearables)", "`POST /sensor/accel` takes `{elderly_id, window: 150 x [x,y,z] in g, fs: 50}`. It answers 503 until a model trained on **real** data is installed (`python ml/export_to_backend.py`); synthetic models are refused unless `ALLOW_SYNTHETIC_ACCEL_MODEL=true` (tests only).",
        "", "## Errors", "400 invalid input, 401 not logged in / wrong key, 403 role not allowed, 404 person not found (or not yours), 503 model not available."]
(root / "docs/API_DOCUMENTATION.md").write_text("\n".join(out) + "\n", encoding="utf-8"); print(len(rows), "routes documented")
